-- ============================================================================
-- v29: bildfilter, mealprep och passmallar för klienter.
--
-- 1. Bildfilter: profilbilder och bilder i chatten granskas på servern
--    (/api/uploads/image, nsfwjs) innan de sparas. Därför får webbläsaren inte
--    längre ladda upp bilder direkt till avatars eller chat-attachments – det
--    gör servern (service role) efter granskningen. PDF och video i chatten
--    laddas upp som förut. Stoppade och flaggade bilder loggas i
--    moderation_events (bara servern/administratören kan läsa).
-- 2. Receptkategorin "meal_prep" (Mealprep) för egna recept och biblioteket.
-- 3. Passmallar för klienter: workout_templates kan ägas av en PT (trainer_id)
--    eller en klient (client_id) – exakt en av dem.
--
-- Körs efter 20261110000000_v28_recipe_photos.sql.
-- ============================================================================

-- ====================================================== 1. bildfilter ===
create table if not exists moderation_events (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid references profiles on delete cascade,
  bucket     text not null check (bucket in ('avatars', 'chat-attachments', 'recipe-images')),
  path       text check (path is null or char_length(path) <= 300),
  action     text not null check (action in ('blocked', 'flagged')),
  reason     text check (reason is null or char_length(reason) <= 200),
  scores     jsonb not null default '{}' check (jsonb_typeof(scores) = 'object'),
  created_at timestamptz not null default now()
);
create index if not exists moderation_events_created_idx on moderation_events (created_at desc);
alter table moderation_events enable row level security;
revoke all on moderation_events from anon, authenticated;
-- Inga policies: bara service role (servern) skriver och läser.

-- Profilbilder: bara servern laddar upp (efter granskning). Läsa/ta bort sin egen behålls.
drop policy if exists "avatars: own write" on storage.objects;
drop policy if exists "avatars: own update" on storage.objects;

-- Chatten: webbläsaren laddar bara upp sådant som inte är bilder (PDF, video).
-- Bilder går via servern och bildfiltret.
drop policy if exists "chat-attachments: parties upload" on storage.objects;
create policy "chat-attachments: parties upload" on storage.objects for insert to authenticated
  with check (
    bucket_id = 'chat-attachments'
    and can_access_client((storage.foldername(name))[1])
    and name !~* '\.(jpe?g|png|webp|gif|heic|heif|avif|bmp|tiff?)$'
  );
update storage.buckets set allowed_mime_types = array['image/webp', 'application/pdf', 'video/mp4', 'video/quicktime', 'video/webm']
  where id = 'chat-attachments';

-- ======================================================== 2. mealprep ===
alter table client_recipes drop constraint if exists client_recipes_goal_types_check;
alter table client_recipes add constraint client_recipes_goal_types_check
  check (goal_types <@ array['high_protein', 'weight_loss', 'pre_workout', 'post_workout', 'quick_easy', 'meal_prep']::text[]);
alter table library_recipes drop constraint if exists library_recipes_goal_types_check;
alter table library_recipes add constraint library_recipes_goal_types_check
  check (goal_types <@ array['high_protein', 'weight_loss', 'pre_workout', 'post_workout', 'quick_easy', 'meal_prep']::text[]);

