on conflict (id) do update set
  slug = excluded.slug, name = excluded.name, servings = excluded.servings, total_minutes = excluded.total_minutes,
  goal_types = excluded.goal_types, items = excluded.items, steps = excluded.steps,
  -- Pexels-länkar uppdateras; foton som laddats upp till Storage (set-recipe-images.mjs) skrivs aldrig över.
  image_url = case
    when excluded.image_url is null then library_recipes.image_url
    when library_recipes.image_url is null or library_recipes.image_url like 'https://images.pexels.com/%' then excluded.image_url
    else library_recipes.image_url
  end,
  nutrition = excluded.nutrition, updated_at = now();
-- END LIBRARY SEED

-- ================================================ 3. klienternas mallar ===
alter table workout_templates alter column trainer_id drop not null;
alter table workout_templates add column if not exists client_id uuid references profiles on delete cascade;
alter table workout_templates add column if not exists created_at timestamptz not null default now();
alter table workout_templates drop constraint if exists workout_templates_owner_check;
alter table workout_templates add constraint workout_templates_owner_check
  check ((trainer_id is null) <> (client_id is null));
alter table workout_templates drop constraint if exists workout_templates_exercises_check;
alter table workout_templates add constraint workout_templates_exercises_check
  check (jsonb_typeof(exercises) = 'array' and jsonb_array_length(exercises) <= 60) not valid;
create index if not exists workout_templates_client_idx on workout_templates (client_id) where client_id is not null;

drop policy if exists "templates: client own" on workout_templates;
create policy "templates: client own" on workout_templates for all to authenticated
  using (client_id = auth.uid()) with check (client_id = auth.uid() and trainer_id is null);
